package vn.xuannhashop.business.inventory.application;
import java.util.*;
import java.time.LocalDate;
import java.math.BigDecimal;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import vn.xuannhashop.business.shared.*;
import vn.xuannhashop.business.shared.security.ActorContext;
import vn.xuannhashop.business.shared.audit.ActivityService;
import vn.xuannhashop.business.reservation.application.ReservationApplication;
@Service
public class StockOperationsService implements StockOperationsApplication {
    private final StockOperationsRepository r;private final ActorContext actor;private final Commands commands;private final ActivityService audit;private final ReservationApplication reservations;
    public StockOperationsService(StockOperationsRepository r,ActorContext actor,Commands commands,ActivityService audit,ReservationApplication reservations){this.r=r;this.actor=actor;this.commands=commands;this.audit=audit;this.reservations=reservations;}
    public Map<String,Object> overview(){actor.require("OWNER","MANAGER","INVENTORY","ACCOUNTANT");var result=new LinkedHashMap<>(r.overview());if(!Set.of("OWNER","ACCOUNTANT").contains(actor.current().role())){for(String group:List.of("receipts","actions")){var rows=(List<Map<String,Object>>)result.get(group);result.put(group,rows.stream().map(row->{var copy=new LinkedHashMap<>(row);copy.remove("unit_cost");copy.remove("recovery_value");return copy;}).toList());}}return result;}
    @Transactional public UUID warehouse(String name,String address,String key){actor.require("OWNER");Checks.text(name,120,"Tên điểm phục vụ/kho");Checks.text(address,400,"Địa chỉ");return commands.once(key,"WAREHOUSE:"+name+":"+address,()->{UUID id=UUID.randomUUID();r.warehouse(id,name.strip(),address.strip());audit.record("WAREHOUSE_CREATED",id,name);return id;});}
    @Transactional public UUID receive(Receipt c,String key){actor.require("OWNER","ACCOUNTANT");if(c==null||c.warehouseId()==null||c.typeId()==null||c.acquiredOn()==null||c.acquiredOn().isAfter(LocalDate.now())||c.usefulLifeMonths()==null||c.usefulLifeMonths()<0||c.usefulLifeMonths()>600||c.lines()==null||c.lines().isEmpty()||c.lines().size()>100)throw DomainException.bad("Lô nhận cần kho, loại, ngày nhận, thời gian phân bổ 0–600 tháng và 1–100 mã.");if(c.warrantyUntil()!=null&&c.warrantyUntil().isBefore(c.acquiredOn()))throw DomainException.bad("Hạn bảo hành không được trước ngày nhận.");Checks.money(c.unitCost());Checks.text(c.supplierName(),160,"Nhà cung cấp");Checks.text(c.documentRef(),180,"Chứng từ");Checks.text(c.reason(),1000,"Căn cứ tiếp nhận");var codes=new HashSet<String>();for(var l:c.lines()){if(l==null||l.code()==null||!l.code().matches("[A-Z0-9-]{3,40}")||!codes.add(l.code()))throw DomainException.bad("Mã phải duy nhất, 3–40 chữ hoa/số/gạch ngang.");Checks.text(l.serialNumber(),120,"Số sê-ri/căn cứ không có sê-ri");}return commands.once(key,"PURCHASE:"+c,()->{r.lockWarehouses(List.of(c.warehouseId()));if(!r.activeType(c.typeId()))throw DomainException.missing();UUID id=UUID.randomUUID();r.receive(id,c,actor.username());audit.record("PURCHASE_RECEIPT_REQUESTED",id,c.documentRef());return id;});}
    private void pending(Map<String,Object> row){if(row==null)throw DomainException.missing();if(!"PENDING".equals(row.get("status")))throw DomainException.conflict("Hồ sơ đã được quyết định.");if(actor.username().equals(row.get("requested_by")))throw DomainException.conflict("Người xác nhận phải khác người lập.");}
    @Transactional public void decideReceipt(UUID id,boolean accepted,String note,String key){actor.require("OWNER");Checks.text(note,1000,"Căn cứ quyết định");commands.once(key,"PURCHASE_DECIDE:"+id+":"+accepted+":"+note,()->{var row=r.receipt(id);pending(row);r.lockWarehouses(List.of((UUID)row.get("warehouse_id")));if(accepted&&!r.activeType((UUID)row.get("type_id")))throw DomainException.conflict("Loại thiết bị không còn hoạt động.");r.decideReceipt(id,accepted,actor.username(),note);audit.record("PURCHASE_RECEIPT_DECIDED",id,accepted+"; "+note);return id;});}
    @Transactional public UUID action(Action c,String key){actor.require("OWNER","MANAGER","INVENTORY");if(c==null||c.equipmentId()==null||c.kind()==null||!Set.of("TRANSFER","DISPOSE").contains(c.kind()))throw DomainException.bad("Chọn chuyển kho hoặc thanh lý và mã thiết bị.");if(c.kind().equals("DISPOSE"))actor.require("OWNER","MANAGER");Checks.text(c.reason(),1000,"Căn cứ");if(c.recoveryValue()==null||c.recoveryValue().signum()<0||c.recoveryValue().scale()>2||c.recoveryValue().compareTo(new BigDecimal("999999999999.99"))>0)throw DomainException.bad("Giá trị thu hồi không hợp lệ.");return commands.once(key,"STOCK_ACTION:"+c,()->{var a=r.asset(c.equipmentId());if(a==null)throw DomainException.missing();var warehouses=new ArrayList<UUID>();warehouses.add((UUID)a.get("warehouse_id"));if(c.kind().equals("TRANSFER")){if(c.toWarehouse()==null||c.toWarehouse().equals(a.get("warehouse_id")))throw DomainException.bad("Chọn kho đích khác kho nguồn.");warehouses.add(c.toWarehouse());}else if(c.toWarehouse()!=null)throw DomainException.bad("Thanh lý không có kho đích.");r.lockWarehouses(warehouses);reservations.requireIdle(c.equipmentId());a=r.asset(c.equipmentId());if(!warehouses.get(0).equals(a.get("warehouse_id")))throw DomainException.conflict("Vị trí đã đổi. Tải lại hồ sơ.");if(!Set.of("READY","AWAIT_ACCEPTANCE","AWAIT_INSPECTION","MAINTENANCE").contains(a.get("state")))throw DomainException.conflict("Thiết bị đang giao/thuê, ngừng khai thác hoặc đã thanh lý.");UUID id=UUID.randomUUID();r.action(id,c,a,actor.username());audit.record("STOCK_ACTION_REQUESTED",c.equipmentId(),c.kind()+"; "+c.reason());return id;});}
    @Transactional public void decideAction(UUID id,boolean accepted,String note,String key){actor.require("OWNER","INVENTORY");Checks.text(note,1000,"Căn cứ giao nhận/quyết định");commands.once(key,"STOCK_ACTION_DECIDE:"+id+":"+accepted+":"+note,()->{var c=r.action(id);pending(c);if(c.get("kind").equals("DISPOSE"))actor.require("OWNER");var warehouses=new ArrayList<UUID>();warehouses.add((UUID)c.get("from_warehouse"));if(c.get("to_warehouse")!=null)warehouses.add((UUID)c.get("to_warehouse"));r.lockWarehouses(warehouses);UUID equipment=(UUID)c.get("equipment_id");reservations.requireIdle(equipment);var a=r.asset(equipment);if(!a.get("state").equals("SUSPENDED")||!a.get("warehouse_id").equals(c.get("from_warehouse")))throw DomainException.conflict("Trạng thái hoặc vị trí thiết bị đã thay đổi.");r.decideAction(id,accepted,actor.username(),note);audit.record("STOCK_ACTION_DECIDED",equipment,c.get("kind")+"; "+accepted+"; "+note);return id;});}
    @Transactional public UUID count(Count c,String key){actor.require("OWNER","MANAGER","INVENTORY");if(c==null||c.warehouseId()==null||c.observedCodes()==null||c.observedCodes().size()>1000)throw DomainException.bad("Cần kho và danh sách mã quan sát (tối đa 1000).");Checks.text(c.reason(),1000,"Căn cứ kiểm kê");if(c.observedCodes().stream().anyMatch(v->v==null||!v.matches("[A-Z0-9-]{3,40}"))||new HashSet<>(c.observedCodes()).size()!=c.observedCodes().size())throw DomainException.bad("Mã kiểm kê không hợp lệ hoặc trùng.");return commands.once(key,"STOCK_COUNT:"+c,()->{r.lockWarehouses(List.of(c.warehouseId()));var assets=r.countAssets(c.warehouseId());if(assets.size()>1000)throw DomainException.bad("Kho vượt 1000 mã, cần chia phạm vi kiểm kê.");UUID id=UUID.randomUUID();r.count(id,c,assets,actor.username());audit.record("STOCK_COUNT_CREATED",id,c.reason());return id;});}
    @Transactional public void decideCount(UUID id,boolean accepted,String note,String key){actor.require("OWNER");Checks.text(note,1000,"Kết luận chênh lệch");commands.once(key,"STOCK_COUNT_DECIDE:"+id+":"+accepted+":"+note,()->{var c=r.count(id);pending(c);if(accepted){UUID warehouse=(UUID)c.get("warehouse_id");r.lockWarehouses(List.of(warehouse));var lines=r.countLines(id);for(var l:lines)reservations.lock((UUID)l.get("equipment_id"));var now=r.countAssets(warehouse);if(now.size()!=lines.size())throw DomainException.conflict("Tồn kho đã thay đổi; lập phiên kiểm kê mới.");for(var l:lines){var a=now.stream().filter(v->v.get("id").equals(l.get("equipment_id"))).findFirst().orElseThrow(()->DomainException.conflict("Vị trí đã đổi; kiểm kê lại."));if(!a.get("version").equals(l.get("version")))throw DomainException.conflict("Thiết bị đã thay đổi; kiểm kê lại.");if(!Boolean.TRUE.equals(l.get("found")))reservations.requireIdle((UUID)l.get("equipment_id"));}}r.decideCount(id,accepted,actor.username(),note);audit.record("STOCK_COUNT_DECIDED",id,accepted+"; "+note);return id;});}
}
